const loopItem =
  $("Loop Assets").item.json ||
  {};

const name =
  loopItem.name;

const content =
  loopItem.content ||
  $json.content ||
  $json.data ||
  $json.body ||
  "";

return [{
  json: {
    client_context:
      loopItem.client_context ||
      {},

    name,

    content,
  },
}];

const clientContext = {
  ...$json,
};

const assets = [
  {
    name: "generation-instructions.txt",
    content: `Create useful, original content based on the runtime inputs.
Return valid HTML only.
Do not invent unsupported claims or statistics.
Keep the response aligned with the supplied client profile and configuration.`
  },
  {
    name: "content-guidelines.md",
    content: `# Content Guidelines
- Use a clear, professional tone.
- Match the requested intent, content type, and target location.
- Prefer concise headings and readable paragraphs.
- Avoid keyword stuffing and repetitive language.
- Use supplied research only as supporting context.`
  },
  {
    name: "quality-rules.md",
    content: `# Quality Rules
- Check that required metadata is present.
- Keep factual statements grounded in supplied context.
- Do not copy source wording.
- Avoid fabricated citations, statistics, or customer claims.
- Produce structurally valid HTML.`
  },
  {
    name: "style-guidelines.md",
    content: `# Style
Write naturally for a general audience.
Use descriptive headings, short paragraphs, and direct language.
Avoid filler and exaggerated marketing language.`
  }
];

return assets.map(asset => ({
  json: {
    client_context: clientContext,
    name: asset.name,
    content: asset.content,
  },
}));

function clean(v) {
  return v === undefined || v === null ? "" : String(v).trim();
}

function norm(v) {
  return clean(v).toLowerCase();
}

function isEmpty(v) {
  return clean(v) === "";
}

function firstPresent(...vals) {
  for (const v of vals) {
    if (!isEmpty(v)) return v;
  }

  return "";
}

const client = $("Loop Clients").item.json || {};
const rows = items.map(item => item.json || {});

const runLog = $items("Read Client Run Log")
  .map(item => item.json || {});

const activeRunId = clean(
  client.__active_run_id ||
  client.active_run_id ||
  ""
);

function getMainPublishStatus(row) {
  return norm(
    firstPresent(
      row.main_publish_status,
      row["Main Publish Status"]
    )
  );
}

function __runFeatureImgWpIdClientContext(row, extra = {}) {
  return [{
    json: {
      ...row,

      __clientWebsite:
        client.Website ||
        client.website ||
        "",

      __clientTab:
        client.Tab ||
        client.tab ||
        "",

      __clientProfile:
        client.Profile ||
        client.profile_url ||
        "",

      __clientAbout:
        client.About ||
        client.config_url ||
        "",

      __wpUsername:
        client.wp_username ||
        "",

      __wpApplicationPassword:
        client.wp_application_password ||
        "",

      __wpCategoryId:
        client["Category ID"] ||
        client.category_id ||
        client.CategoryID ||
        "",

      __distributionTier:
        client.distribution_tier ||
        client["Distribution Tier"] ||
        "",


      __contentAiModel:
        client.content_ai_model ||
        client["Content AI Model"] ||
        "gpt-4.1-mini",
      __distributionAiModel:
  client.distribution_ai_model ||
  client["Distribution AI Model"] ||
  "gpt-4.1-mini",

      __selectedTargets:
        client.selected_targets ||
        client["Selected Targets"] ||
        "",
__reportCcEmail:
  client.report_cc_email ||
  client["Report CC Email"] ||
  "",
      __runMode:
        client.__run_mode ||
        "cron",

      __clientKey:
        client.__client_key ||
        "",

      __clientDbRowNumber:
        client.row_number ||
        "",

      __dailyPostLimit:
        client.__daily_post_limit ??
        1,

      __runEveryHours:
        client.__run_every_hours ??
        24,

      __ignoreSchedule:
        client.__ignore_schedule ||
        false,

      __ignoreDailyLimit:
        client.__ignore_daily_limit ||
        false,

      __runCountsTowardQuota:
        client.__run_counts_toward_quota ||
        false,
      __scheduleKey:
  client.__schedule_key ||
  "",

      ...extra,
    },
  }];
}

// Resume the exact row associated with an unfinished run.
if (activeRunId) {
  const activeRun = runLog.find(run =>
    clean(run.run_id) === activeRunId
  );

  if (!activeRun) {
    return [{
      json: {
        skip_client: true,
        message:
          `active_run_id ${activeRunId} exists, but the matching client_run_log row was not found.`,
        tab:
          client.Tab ||
          client.tab ||
          "",
        website:
          client.Website ||
          client.website ||
          "",
      },
    }];
  }

  if (norm(activeRun.status) === "needs_review") {
    return [{
      json: {
        skip_client: true,
        message:
          `Run ${activeRunId} requires manual review.`,
        tab:
          client.Tab ||
          client.tab ||
          "",
        website:
          client.Website ||
          client.website ||
          "",
      },
    }];
  }

  const lockedRow = rows.find(row =>
    clean(row.row_number) ===
    clean(activeRun.source_row_number)
  );

  if (!lockedRow) {
    return [{
      json: {
        skip_client: true,
        message:
          `Run ${activeRunId} references missing keyword row ${activeRun.source_row_number}.`,
        tab:
          client.Tab ||
          client.tab ||
          "",
        website:
          client.Website ||
          client.website ||
          "",
      },
    }];
  }

  const stage =
    clean(activeRun.stage || "STARTED")
      .toUpperCase();

  return __runFeatureImgWpIdClientContext(lockedRow, {
    __retryExistingPublish:
      stage === "MAIN_PUBLISH_FAILED",

    __activeRunId:
      activeRunId,

    __runStage:
      stage,

    __runLogStatus:
      activeRun.status ||
      "active",

    __runSourcePostUrl:
      activeRun.source_post_url ||
      "",

    __runMainPostId:
      activeRun.main_post_id ||
      "",

    __runDistributionStatus:
      activeRun.distribution_status ||
      "",
    __runFeatureImgUrl:
  activeRun.feature_img_url ||
  "",
    __runFeatureImgStatus:
  activeRun.feature_img_status ||
  "",

__runImageWarning:
  activeRun.image_warning ||
  "",
__runCountsTowardQuota:
  clean(activeRun.run_counts_toward_quota) === ""
    ? (client.__run_counts_toward_quota || false)
    : (
        activeRun.run_counts_toward_quota === true ||
        ["true", "yes", "1"].includes(
          norm(activeRun.run_counts_toward_quota)
        )
      ),
__runFeatureImgWpId:
  activeRun.feature_img_wp_id ||
  "",
  });
}

// No active run: keep the existing priority order.
const publishRetryRows = rows.filter(row =>
  norm(row.Status) === "done" &&
  ["", "publish_failed"].includes(
    getMainPublishStatus(row)
  ) &&
  !isEmpty(row.content_output) &&
  isEmpty(
    firstPresent(
      row.source_post_url,
      row["Source Post URL"]
    )
  )
);

const generationRows = rows.filter(row => {
  const status = norm(row.Status);

  return (
    ["", "failed", "failed_metadata"].includes(status) &&
    getMainPublishStatus(row) === "" &&
    !isEmpty(row["Primary keyword"])
  );
});

const retryExistingPublish =
  publishRetryRows.length > 0;

const row = retryExistingPublish
  ? publishRetryRows[0]
  : generationRows[0];

if (!row) {
  return [{
    json: {
      skip_client: true,
      message:
        "No article-generation row or valid failed-publish retry row was found.",
      tab:
        client.Tab ||
        client.tab ||
        "",
      website:
        client.Website ||
        client.website ||
        "",
    },
  }];
}

return __runFeatureImgWpIdClientContext(row, {
  __retryExistingPublish:
    retryExistingPublish,

  __activeRunId:
    "",

  __runStage:
    retryExistingPublish
      ? "MAIN_PUBLISH_FAILED"
      : "STARTED",
});

const out = {};

const first =
  items[0]?.json ||
  {};

for (const item of items) {
  out[item.json.name] =
    item.json.content;
}

return [{
  json: {
    ...(
      first.client_context ||
      {}
    ),

    assets:
      out,
  },
}];

const runtime = $json || {};

return [{
  json: {
    ...runtime,

    // Public portfolio version: no company/client repository links.
    profile_url: "",
    config_url: "",
    profile_raw_url: "",
    config_raw_url: "",
  }
}];

const j = $json || {};

return [{
  json: {
    business_name: "Demo Business",
    website: j.website || "example.com",
    target_audience: "General audience",
    brand_voice: "Clear, helpful, professional",
    description: "Generic portfolio demo profile. Replace with your own non-sensitive data."
  }
}];

return [{
  json: {
    content_preferences: {
      tone: "professional",
      depth: "practical",
      use_headings: true
    },
    publishing_preferences: {
      default_status: "draft"
    },
    note: "Generic portfolio configuration. Replace with your own non-sensitive settings."
  }
}];

// Assemble a single payload for the AI node:
// - runtime vars (keyword, intent, etc.)
// - engine assets (github raw files) already in $json.assets
// - client profile JSON from "Fetch Client Profile"
// - client config/about JSON from "Fetch Client Profile1"

function safeJson(v) {
  if (!v) return null;
  if (typeof v === 'object') return v;
  try { return JSON.parse(v); } catch(e) { return null; }
}

const ctx = $input.first().json || {};

const runtime = ctx;
const prepared = ctx;

const profileResp = ctx.client_profile_response || {};
const configResp  = ctx.client_config_response || {};

// Depending on HTTP node settings, data could be in:
// - json (already parsed)
// - data (string)
// - body (string)
const profileJson =
  safeJson(profileResp?.data) ||
  safeJson(profileResp?.body) ||
  (typeof profileResp === 'object' ? profileResp : null);

const configJson =
  safeJson(configResp?.data) ||
  safeJson(configResp?.body) ||
  (typeof configResp === 'object' ? configResp : null);

// Build final payload for AI generation
return [{
  json: {
    // runtime controls
    website: runtime.website,
    tab: runtime.tab,
    row_number: runtime.row_number,
    keyword: runtime.keyword,
    target_location: runtime.target_location,
    intent: runtime.intent,
    topic_mode: runtime.topic_mode,
    content_type: runtime.content_type,
    output_format: runtime.output_format,
    faq: runtime.faq,
    meta_field: runtime.meta_field,
    cta_policy: runtime.cta_policy,
web_search: runtime.web_search || false,
prompt_for_web_search: runtime.prompt_for_web_search || "",
web_research_summary: "",
web_research_sources: "",
web_search_used: false,
    // where we fetched from
    profile_url: prepared.profile_url,
    config_url: prepared.config_url,
    profile_raw_url: prepared.profile_raw_url,
    config_raw_url: prepared.config_raw_url,

    // combined rules from GitHub
    engine_assets: prepared.assets,

    // the 2 client URLs content (JSON)
    client_profile: profileJson,
    client_config: configJson,
    distribution_mode:
  runtime.distribution_mode || "",

distribution_targets:
  runtime.distribution_targets || "",

content_ai_model:
  runtime.content_ai_model ||
  "gpt-4.1-mini",
  }
}];

const html = $json.output || $json.ai_html || "";

if (!html || typeof html !== "string") {
  return [{
    json: {
      tab: $json.tab || "",
      row_number: $json.row_number || "",
      status: "FAILED",
      generated_title: "",
      slug: "",
      meta_title: "",
      meta_description: "",
      content_output: "",
      schema_jsonld: "",
      updated_at: new Date().toISOString(),
      error: "AI HTML not found"
    }
  }];
}

const clean = (s) => (s || "").replace(/\r/g, "").trim();
const stripTags = (s) => (s || "").replace(/<[^>]+>/g, "");

function stripMarkdownCodeFences(input) {
  let out = String(input || "").replace(/\r/g, "").trim();

  // Remove opening fences like:
  // ```html
  // ``` HTML
  // “`html
  // “```html
  out = out.replace(
    /^[\s\uFEFF]*(?:[“”"'']\s*)?`{1,3}\s*(?:html|xml|json|javascript|js)?\s*/i,
    ""
  );

  // Remove closing fences like:
  // ```
  // “`
  // ”```
  out = out.replace(
    /\s*(?:[“”"'']\s*)?`{1,3}(?:\s*[“”"''])?\s*$/g,
    ""
  );

  return out.trim();
}

function removeHiddenMetaBlocks(input) {
  return String(input || "")
    // Remove hidden metadata block from the final published body
    .replace(/<pre\b[^>]*style=["'][^"']*display\s*:\s*none[^"']*["'][^>]*>[\s\S]*?<\/pre>/gi, "")
    // Remove older seo-meta block from the final published body
    .replace(/<div\b[^>]*class=["'][^"']*\bseo-meta\b[^"']*["'][^>]*>[\s\S]*?<\/div>/gi, "");
}

const compressHtml = (s) =>
  clean(s)
    .replace(/\n+/g, " ")
    .replace(/\s{2,}/g, " ")
    .replace(/>\s+</g, "><");

function cleanPublishedHtml(input) {
  return compressHtml(
    removeHiddenMetaBlocks(
      stripMarkdownCodeFences(input)
    )
  );
}

const h1Match = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);

const schemaMatches = [...html.matchAll(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)];
const schemaJsonld = schemaMatches.map(m => compressHtml(m[1])).join(" ");

let slug = "";
let metaTitle = "";
let metaDescription = "";

// Supports both the older <div class="seo-meta"> block and the current hidden <pre style="display:none;"> block.
const divMetaMatch = html.match(/<div[^>]*class=["']seo-meta["'][^>]*>([\s\S]*?)<\/div>/i);
const preMetaMatch = html.match(/<pre[^>]*style=["'][^"']*display\s*:\s*none[^"']*["'][^>]*>([\s\S]*?)<\/pre>/i);
const metaBlockRaw = divMetaMatch?.[1] || preMetaMatch?.[1] || "";

if (metaBlockRaw) {
  const metaBlock = clean(stripTags(metaBlockRaw.replace(/<br\s*\/?>/gi, "\n")));

  const slugMatch = metaBlock.match(/^slug:\s*(.+)$/im);
  const metaTitleMatch = metaBlock.match(/^meta[\s_-]*title:\s*(.+)$/im);
  const metaDescriptionMatch = metaBlock.match(/^meta[\s_-]*description:\s*(.+)$/im);

  slug = slugMatch ? clean(slugMatch[1]) : "";
  metaTitle = metaTitleMatch ? clean(metaTitleMatch[1]) : "";
  metaDescription = metaDescriptionMatch ? clean(metaDescriptionMatch[1]) : "";
}

const generatedTitle = h1Match ? clean(stripTags(h1Match[1])) : "";
const requiredFields = {
  slug,
  meta_title: metaTitle,
  meta_description: metaDescription,
  schema_jsonld: schemaJsonld,
};

const missingFields = Object.entries(requiredFields)
  .filter(([key, value]) => !String(value || "").trim())
  .map(([key]) => key);

const metaOk = missingFields.length === 0;

const metadataError = metaOk
  ? ""
  : `Required AI output fields missing: ${missingFields.join(", ")}`;
return [{
  json: {
    tab: $json.tab || "",
    row_number: $json.row_number || "",
    status: metaOk ? "DONE" : "FAILED_METADATA",
    generated_title: generatedTitle,
    slug,
    meta_title: metaTitle,
    meta_description: metaDescription,
    content_output: cleanPublishedHtml(html),
    schema_jsonld: schemaJsonld,
    updated_at: new Date().toISOString(),
    error: metadataError
  }
}];

const first = $input.first();
const username = first.json.wp_username || '';
const appPassword = (first.json.wp_application_password || '').replace(/\s+/g, '');

const auth = 'Basic ' + Buffer.from(`${username}:${appPassword}`).toString('base64');

return [{
  json: {
    ...first.json,
    wp_basic_auth: auth
  }
}];

const base = $("Assemble Prompt Payload").item.json || $json || {};

return [{
  json: {
    ...base,
    web_research_summary: "",
    web_research_sources: "",
    web_search_used: false
  }
}];

