const original = $("Assemble Prompt Payload").item.json || {};
const res = $json || {};

const candidate = res.candidates?.[0] || {};
const parts = candidate.content?.parts || [];

// Collect text parts, remove duplicates, clean citation placeholders.
const seenText = new Set();
const text = parts
  .map(p => String(p.text || "").trim())
  .filter(Boolean)
  .map(t => t.replace(/\[cite:\s*\d+(?:,\s*\d+)*\]/gi, "").trim())
  .filter(t => {
    const key = t.toLowerCase();
    if (seenText.has(key)) return false;
    seenText.add(key);
    return true;
  })
  .join("\n\n")
  .trim();

const chunks =
  candidate.groundingMetadata?.groundingChunks ||
  candidate.grounding_metadata?.grounding_chunks ||
  [];

const seenSources = new Set();
const sources = chunks
  .map((c, index) => {
    const web = c.web || {};
    const title = web.title || `Source ${index + 1}`;
    const uri = web.uri || "";
    if (!uri || seenSources.has(uri)) return "";
    seenSources.add(uri);
    return `${title}: ${uri}`;
  })
  .filter(Boolean)
  .join("\n");

return [{
  json: {
    ...original,
    web_research_summary: text,
    web_research_sources: sources,
    web_search_used: true
  }
}];

