const original = $("Build Claude Article Request").first().json || {};
const res = $json || {};

const output = (res.content || [])
  .filter(p => p.type === "text" && p.text)
  .map(p => p.text)
  .join("\n\n")
  .trim();

return [{
  json: {
    ...original,
    output,
    claude_message_id: res.id || "",
    claude_usage: res.usage || {}
  }
}];

const j = $json || {};

const prompt = `PRIMARY KEYWORD:
${j.keyword}

TARGET LOCATION:
${j.target_location}

INTENT:
${j.intent}

TOPIC MODE:
${j.topic_mode}

CONTENT TYPE:
${j.content_type}

OUTPUT FORMAT:
${j.output_format}

CLIENT PROFILE:
${JSON.stringify(j.client_profile, null, 2)}

CLIENT CONFIG:
${JSON.stringify(j.client_config, null, 2)}

OPTIONAL RESEARCH:
${j.web_research_summary || "No external research was supplied."}

RESEARCH SOURCES:
${j.web_research_sources || ""}

GENERIC CONTENT RULES:
${JSON.stringify(j.engine_assets, null, 2)}

CRITICAL OUTPUT FORMAT:
Start the output with this hidden metadata block exactly:

<pre style="display:none;">
Slug: [seo-friendly-url-slug]
Meta Title: [meta title under 60 characters]
Meta Description: [meta description under 160 characters]
</pre>

Then output the full article HTML.

Rules:
- Do not use markdown fences.
- Do not invent unsupported facts or statistics.
- Do not copy source wording.
- Return only the final generated content.`;

return [{
  json: {
    ...j,
    claude_model: j.content_ai_model || "claude-sonnet-4-5-20250929",
    claude_prompt: prompt
  }
}];

return [{
  json:
    $("Should Write Source URL?").item.json
}];

let context = null;

try {
  context = $("Save Created Post Context").item.json;
} catch {}

if (!context) {
  try {
    context = $("Mark Publish Skipped").item.json;
  } catch {}
}

return [{
  json: context || $json
}];

function errorText(v) {
  if (!v) {
    return "Unknown image generation error.";
  }

  if (typeof v === "string") {
    return v;
  }

  if (v.error) {
    if (typeof v.error === "string") {
      return v.error;
    }

    if (v.error.message) {
      return String(v.error.message);
    }

    if (v.error.description) {
      return String(v.error.description);
    }
  }

  if (v.message) {
    return String(v.message);
  }

  if (v.errorMessage) {
    return String(v.errorMessage);
  }

  try {
    return JSON.stringify(v).slice(0, 1000);
  } catch {
    return "Unknown image generation error.";
  }
}

const base =
  $("Manual Publish Flags").item.json ||
  {};

const failure =
  $json ||
  {};

const warning =
  `Image generation failed; continued without image: ${errorText(failure)}`;

return [{
  json: {
    ...base,

    tab:
      base.tab ||
      "",

    row_number:
      base.row_number ||
      "",

    feature_img_url:
      "",

    feature_img_wp_id:
      "",

    feature_img_status:
      "FAILED_CONTINUED",

    image_generation_failed:
      true,

    image_warning:
      warning,

