}

function getErrorText(value) {
  const j = value || {};

  const err =
    j.error ||
    j.errorMessage ||
    j.errorDescription ||
    "";

  if (typeof err === "string" && err.trim()) {
    return err.trim();
  }

  if (err?.message) {
    return String(err.message);
  }

  if (err?.description) {
    return String(err.description);
  }

  if (j.code && j.message) {
    return `${j.code}: ${j.message}`;
  }

  return "";
}

function extractRows(value) {
  if (Array.isArray(value)) {
    return value;
  }

  if (Array.isArray(value?.data)) {
    return value.data;
  }

  if (Array.isArray(value?.body)) {
    return value.body;
  }

  if (value?.id && value?.slug) {
    return [value];
  }

  return [];
}

const base =
  $("Prepare WP Post Auth").item.json ||
