const lookupError =
  getErrorText(response);

const rows =
  extractRows(response);

const requestedSlug =
  norm(base.wp_post_slug);

const existing =
  rows.find(row =>
    norm(row.slug) === requestedSlug
  ) || null;

const isRecovery =
