}];

function clean(v) {
  return v === undefined || v === null
    ? ""
    : String(v).trim();
}

function norm(v) {
  return clean(v).toLowerCase();
}

function yes(v, fallback = true) {
  const x = norm(v);

  if (!x) return fallback;

  return [
    "yes",
    "true",
    "1",
    "enabled",
    "on",
  ].includes(x);
}

function num(v, fallback = 0) {
  const n = Number(v);

  return Number.isFinite(n)
    ? n
    : fallback;
}

function domainOnly(v) {
  return norm(v)
    .replace(/^https?:\/\//, "")
    .replace(/^www\./, "")
    .replace(/\/+$/, "");
}

function getNodeJson(name) {
  try {
    return $items(name)[0]?.json || {};
  } catch (e) {
    return {};
  }
}

function dateMs(v) {
  const ms = Date.parse(clean(v));

  return Number.isFinite(ms)
    ? ms
    : null;
}

function torontoParts(date) {
  const parts =
    new Intl.DateTimeFormat(
      "en-CA",
      {
        timeZone: "America/Toronto",
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
        weekday: "short",
        hour: "2-digit",
        minute: "2-digit",
        hourCycle: "h23",
      }
    ).formatToParts(date);

  const get = type =>
    parts.find(
      part => part.type === type
    )?.value || "";

  return {
    dateKey:
      `${get("year")}-${get("month")}-${get("day")}`,

    weekday:
      norm(get("weekday"))
        .slice(0, 3),

    minutes:
      Number(get("hour") || 0) * 60 +
      Number(get("minute") || 0),
  };
}

function parseScheduleTime(value) {
  const match =
    clean(value).match(
      /^(\d{1,2}):(\d{2})$/
    );

  if (!match) {
    return null;
  }

  const hour =
    Number(match[1]);

  const minute =
    Number(match[2]);

  if (
    !Number.isInteger(hour) ||
    !Number.isInteger(minute) ||
    hour < 0 ||
    hour > 23 ||
    minute < 0 ||
    minute > 59
  ) {
    return null;
  }

  return {
    key:
      `${String(hour).padStart(2, "0")}:` +
      `${String(minute).padStart(2, "0")}`,

    minutes:
      hour * 60 + minute,
  };
}

function parseScheduleTimes(value) {
  const seen =
    new Set();

  return clean(value)
    .split(/[,;\n]+/)
    .map(parseScheduleTime)
    .filter(Boolean)
    .filter(slot => {
      if (seen.has(slot.key)) {
        return false;
      }

      seen.add(slot.key);
      return true;
    })
    .sort(
      (a, b) =>
        a.minutes - b.minutes
    );
}

function scheduleDayMatches(
  value,
  weekday
) {
  const x =
    norm(value);

  if (
    [
      "daily",
      "everyday",
      "every day",
      "all days",
    ].includes(x)
  ) {
    return true;
  }

  if (x === "weekdays") {
    return [
      "mon",
      "tue",
      "wed",
      "thu",
      "fri",
    ].includes(weekday);
  }

  if (x === "weekends") {
    return [
      "sat",
      "sun",
    ].includes(weekday);
  }

  const aliases = {
    mon: "mon",
    monday: "mon",

    tue: "tue",
    tues: "tue",
    tuesday: "tue",

    wed: "wed",
    wednesday: "wed",

    thu: "thu",
    thur: "thu",
    thurs: "thu",
    thursday: "thu",

    fri: "fri",
    friday: "fri",

    sat: "sat",
    saturday: "sat",

    sun: "sun",
    sunday: "sun",
  };

  return x
    .split(/[,;\n]+/)
    .map(
      token =>
        aliases[norm(token)]
    )
    .filter(Boolean)
    .includes(weekday);
}

function rowCountsTowardQuota(row) {
  const raw =
    clean(
      row.run_counts_toward_quota
    );

  // Preserve quota compatibility
  // with older log rows.
  return raw === ""
    ? true
    : yes(raw, false);
}

const manualCtx =
  getNodeJson(
    "Manual Run Settings"
  );

const cronCtx =
  getNodeJson(
    "Cron Run Settings"
  );

const ctx =
  Object.keys(manualCtx).length
    ? manualCtx
    : cronCtx;

const runMode =
  norm(
    ctx.run_mode ||
    "cron"
  );

const selectedClient =
  domainOnly(
    ctx.selected_client ||
    ""
  );

const ignoreSchedule =
  ctx.ignore_schedule === true ||
  [
    "yes",
    "true",
    "1",
  ].includes(
    norm(ctx.ignore_schedule)
  );

const ignoreDailyLimit =
  ctx.ignore_daily_limit === true ||
  [
    "yes",
    "true",
    "1",
  ].includes(
    norm(ctx.ignore_daily_limit)
  );

const runCountsTowardQuota =
  ctx.run_counts_toward_quota === true ||
  [
    "yes",
    "true",
    "1",
  ].includes(
    norm(
      ctx.run_counts_toward_quota
    )
  );

const allEnabledClients =
  $items("GET DB1")
    .map(item => item.json || {})
    .filter(client =>
      yes(client.enabled, true)
    );

let clients =
  allEnabledClients;

const runLog =
  $items("Read Client Run Log")
    .map(
      item =>
        item.json || {}
    );

const now =
  new Date();

const nowMs =
  now.getTime();

const local =
  torontoParts(now);

// Prevent another Main Flow from
// starting while one is probably running.
const freshActiveMs =
  90 * 60 * 1000;

function clientKeyOf(client) {
  return domainOnly(
    client.Website ||
    client.website ||
    client.Tab ||
    client.tab
  );
}

function buildClientPayload(
  client,
  extra = {}
) {
  const clientKey =
    clientKeyOf(client);

  return {
    ...client,

    __run_mode:
      runMode,

    __client_key:
      clientKey,

    __active_run_id:
      extra.activeRunId ||
      "",

    __daily_post_limit:
      Math.max(
        1,
        num(
          client.daily_post_limit,
          1
        )
      ),

    __run_every_hours:
      Math.max(
        0,
        num(
          client.run_every_hours,
          24
        )
      ),

    __ignore_schedule:
      ignoreSchedule,

    __ignore_daily_limit:
      ignoreDailyLimit,

    __run_counts_toward_quota:
      runCountsTowardQuota,

    __schedule_key:
      extra.scheduleKey ||
      "",

    // Diagnostic fields.
    __scheduler_candidate_type:
      extra.candidateType ||
      "",

    __scheduler_priority:
      extra.priority ?? 0,

    __scheduler_due_at:
      extra.dueAt ||
      "",
  };
}

// Manual runs keep their current
// schedule and quota bypass behavior.
if (runMode === "manual") {
  if (!selectedClient) {
    throw new Error(
      "Manual selected_client is empty."
    );
  }

  const client =
    clients.find(row => {
      const ids = [
        row.Website,
        row.website,
        row.Tab,
        row.tab,
      ]
        .map(domainOnly)
        .filter(Boolean);

      return ids.includes(
        selectedClient
      );
    });

  if (!client) {
    throw new Error(
      `Manual selected_client ${selectedClient} ` +
      `was not found or is disabled.`
    );
  }

  const activeRunId =
    clean(
      client.active_run_id ||
      client["Active Run ID"]
    );

  const activeRun =
    activeRunId
      ? runLog.find(
          row =>
            clean(row.run_id) ===
            activeRunId
        )
      : null;

  return [{
    json:
      buildClientPayload(
        client,
        {
          activeRunId,

          scheduleKey:
            clean(
              activeRun?.schedule_key
            ),

          candidateType:
            activeRunId
              ? "manual_resume"
              : "manual_new",

          priority:
            0,

          dueAt:
            new Date()
              .toISOString(),
        }
      ),
  }];
}

// Cron runs require
// scheduler_enabled.
clients =
  clients.filter(
    client =>
      yes(
        client.scheduler_enabled,
        true
      )
  );

// Global lock.
// A fresh active run prevents any
// second heavy client from starting.
const hasFreshActiveRun =
  allEnabledClients.some(client => {
    const activeRunId =
      clean(
        client.active_run_id ||
        client["Active Run ID"]
      );

    if (!activeRunId) {
      return false;
    }

    const activeRun =
      runLog.find(
        row =>
          clean(row.run_id) ===
          activeRunId
      );

    if (
      !activeRun ||
      norm(activeRun.status) !==
        "active"
    ) {
      return false;
    }

    const updatedMs =
      dateMs(
        activeRun.updated_at
      ) ??
      dateMs(
        activeRun.started_at
      );

    return (
      updatedMs !== null &&
      nowMs - updatedMs <
        freshActiveMs
    );
  });

if (hasFreshActiveRun) {
  return [];
}

const candidates = [];

for (const client of clients) {
  const clientKey =
    clientKeyOf(client);

  if (!clientKey) {
    continue;
  }

  const activeRunId =
    clean(
      client.active_run_id ||
      client["Active Run ID"]
    );

  const dailyLimit =
    Math.max(
      1,
      num(
        client.daily_post_limit,
        1
      )
    );

  const runEveryHours =
    Math.max(
      0,
      num(
        client.run_every_hours,
        24
      )
    );

  const clientRuns =
    runLog.filter(
      row =>
        domainOnly(
          row.client_key
        ) === clientKey
    );

  // Existing unfinished run.
  if (activeRunId) {
    const activeRun =
      runLog.find(
        row =>
          clean(row.run_id) ===
          activeRunId
      );

    // Broken active_run_id should not
    // outrank valid new scheduled work.
if (!activeRun) {
  // Broken active_run_id requires manual cleanup,
  // but must not block valid scheduled clients.
  continue;
}

    const status =
      norm(activeRun.status);

    // needs_review does not block
    // other clients.
    if (
      status ===
      "needs_review"
    ) {
      continue;
    }

    const retryCount =
      Math.max(
        0,
        num(
          activeRun.retry_count,
          0
        )
      );

    const nextRetryMs =
      dateMs(
        activeRun.next_retry_at
      );

    const updatedMs =
      dateMs(
        activeRun.updated_at
      ) ??
      dateMs(
        activeRun.started_at
      ) ??
      0;

    if (
      status ===
        "retry_pending" &&
      nextRetryMs !== null &&
      nextRetryMs > nowMs
    ) {
      continue;
    }

    // 0–2 retries: high priority.
    // More than 2: below new runs.
    const priority =
      retryCount > 2
        ? 3
        : 1;

    const dueAtMs =
      status ===
      "retry_pending"
        ? (
            nextRetryMs ??
            updatedMs
          )
        : updatedMs;

    candidates.push({
      priority,

      dueAtMs,

      rowNumber:
        num(
          client.row_number,
          999999
        ),

      json:
        buildClientPayload(
          client,
          {
            activeRunId,

            scheduleKey:
              clean(
                activeRun.schedule_key
              ),

            candidateType:
              priority === 3
                ? "deprioritized_resume"
                : "resume",

            priority,

            dueAt:
              dueAtMs
                ? new Date(
                    dueAtMs
                  ).toISOString()
                : "",
          }
        ),
    });

    continue;
  }

  const publishedToday =
    clientRuns.filter(row => {
      if (
        !rowCountsTowardQuota(
          row
        )
      ) {
        return false;
      }

      const publishedMs =
        dateMs(
          row.main_published_at
        );

      if (
        publishedMs === null
      ) {
        return false;
      }

      return (
        torontoParts(
          new Date(publishedMs)
        ).dateKey ===
        local.dateKey
      );
    });

  if (
    !ignoreDailyLimit &&
    publishedToday.length >=
      dailyLimit
  ) {
    continue;
  }

  const rawScheduleTime =
    clean(
      client.schedule_time ||
      client["Schedule Time"]
    );

  const rawScheduleDays =
    clean(
      client.schedule_days ||
      client["Schedule Days"]
    );

  // New calendar scheduling.
  if (rawScheduleTime) {
    const slots =
      parseScheduleTimes(
        rawScheduleTime
      );

    if (
      !slots.length ||
      (
        !ignoreSchedule &&
        !scheduleDayMatches(
          rawScheduleDays,
          local.weekday
        )
      )
    ) {
      continue;
    }

    const dueSlots =
      slots.filter(slot => {
        if (
          !ignoreSchedule &&
          local.minutes <
            slot.minutes
        ) {
          return false;
        }

        const scheduleKey =
          `${clientKey}|` +
          `${local.dateKey}|` +
          `${slot.key}`;

        return !runLog.some(
          row =>
            clean(
              row.schedule_key
            ) ===
            scheduleKey
        );
      });

    if (!dueSlots.length) {
      continue;
    }

    // Oldest unused slot first.
    const selectedSlot =
      dueSlots[0];

    const scheduleKey =
      `${clientKey}|` +
      `${local.dateKey}|` +
      `${selectedSlot.key}`;

    const dueAtMs =
      nowMs -
      Math.max(
        0,
        local.minutes -
          selectedSlot.minutes
      ) *
      60 *
      1000;

    candidates.push({
      priority:
        2,

      dueAtMs,

      rowNumber:
        num(
          client.row_number,
          999999
        ),

      json:
        buildClientPayload(
          client,
          {
            scheduleKey,

            candidateType:
              "scheduled_new",

            priority:
              2,

            dueAt:
              new Date(
                dueAtMs
              ).toISOString(),
          }
        ),
    });

    continue;
  }

  // Temporary fallback for clients
  // not migrated to schedule_time.
  const publishedRuns =
    clientRuns
      .map(
        row =>
          dateMs(
            row.main_published_at
          )
      )
      .filter(
        ms =>
          ms !== null
      )
      .sort(
        (a, b) =>
          b - a
      );

  const latestPublishedMs =
    publishedRuns[0] ??
    null;

  if (
    !ignoreSchedule &&
    latestPublishedMs !== null &&
    runEveryHours > 0
  ) {
    const dueAtMs =
      latestPublishedMs +
      runEveryHours *
      60 *
      60 *
      1000;

    if (dueAtMs > nowMs) {
      continue;
    }
  }

  const legacyDueAtMs =
    latestPublishedMs === null
      ? 0
      : (
          latestPublishedMs +
          runEveryHours *
          60 *
          60 *
          1000
        );

  candidates.push({
    priority:
      4,

    dueAtMs:
      legacyDueAtMs,

    rowNumber:
      num(
        client.row_number,
        999999
      ),

    json:
      buildClientPayload(
        client,
        {
          candidateType:
            "legacy_interval",

          priority:
            4,

          dueAt:
            legacyDueAtMs
              ? new Date(
                  legacyDueAtMs
                ).toISOString()
              : "",
        }
      ),
  });
}

candidates.sort(
  (a, b) =>
    a.priority -
      b.priority ||

    a.dueAtMs -
      b.dueAtMs ||

    a.rowNumber -
      b.rowNumber
);

return candidates.length
  ? [{
      json:
        candidates[0].json,
    }]
  : [];

function clean(v) {
  return v === undefined || v === null
    ? ""
    : String(v).trim();
}

function domainOnly(v) {
  return clean(v)
    .toLowerCase()
    .replace(/^https?:\/\//, "")
    .replace(/^www\./, "")
    .replace(/\/+$/, "");
}

const client =
  $("Loop Clients").item.json ||
  {};

const scheduleKey =
  clean(client.__schedule_key);

if (!scheduleKey) {
  // Manual and legacy interval runs do not
  // need calendar-slot consumption.
  return [];
}

const now =
  new Date().toISOString();

const clientKey =
  clean(client.__client_key) ||
  domainOnly(
    client.Website ||
    client.website ||
    client.Tab ||
    client.tab
  );

const missingSheet =
  $json.missing_sheet === true;

const reason =
  clean(
    $json.message ||
    $json.reason
  ) ||
  (
    missingSheet
      ? "Client sheet was unavailable."
      : "No eligible keyword row was available."
  );

const stage =
  missingSheet
    ? "MISSING_SHEET"
    : "NO_ELIGIBLE_ROW";

const runId =
  `schedule-skip-${scheduleKey}`
    .replace(
      /[^a-zA-Z0-9._-]+/g,
      "-"
    );

return [{
  json: {
    run_id:
      runId,

    client_key:
      clientKey,

    source_tab:
      client.Tab ||
      client.tab ||
      "",

    source_row_number:
      "",

    keyword:
      "",

    status:
      "skipped",

    stage,

    started_at:
      now,

    updated_at:
      now,

    next_retry_at:
      "",

    retry_count:
      0,

    error:
      reason,

    source_post_url:
      "",

    main_post_id:
      "",

    main_published_at:
      "",

    distribution_status:
      "",

    completed_at:
      now,

    run_counts_toward_quota:
      false,

    feature_img_status:
      "",

    image_warning:
      "",

    schedule_key:
      scheduleKey,
  },
}];
